const normalizeCatalog=(raw:any):Catalog=>{
 const x={...seed,...(raw||{})};
 return {...x,theme:(['classic','luxury','neon','minimal','food','glass','market','vintage','pastel','industrial','botanical','bold','ocean','sunset','lavender','candy','emerald','coral','arctic','midnight','royal','desert','rose','cyber','mono','citrus','coffee','berry','sky','terra','aurora','pearl','carbon'].includes(x.theme)?x.theme:'classic') as Theme,font:(['system','inter','montserrat','playfair','nunito','space'].includes(x.font)?x.font:'system') as Font,shape:(['square','soft','round','pill'].includes(x.shape)?x.shape:'soft') as Shape,coverShape:(['square','soft','round','pill'].includes(x.coverShape)?x.coverShape:(x.shape||'round')) as Shape,productShape:(['square','soft','round','pill'].includes(x.productShape)?x.productShape:(x.shape||'soft')) as Shape,titleSize:Math.max(22,Math.min(64,Number(x.titleSize)||38)),descriptionSize:Math.max(12,Math.min(30,Number(x.descriptionSize)||16)),categories:Array.isArray(x.categories)?x.categories:seed.categories,products:Array.isArray(x.products)?x.products:[]};
};
