const uid=()=>crypto.randomUUID();

async function convertHeic(blob:Blob):Promise<Blob>{const w=window as any;if(w.heic2any)return await w.heic2any({blob,toType:'image/jpeg',quality:.92}) as Blob;await new Promise<void>((resolve,reject)=>{const existing=document.querySelector('script[data-heic-converter]') as HTMLScriptElement|null;if(existing){existing.addEventListener('load',()=>resolve(),{once:true});existing.addEventListener('error',()=>reject(new Error('No se pudo cargar el conversor HEIC.')),{once:true});return}const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/heic2any@0.0.4/dist/heic2any.min.js';script.async=true;script.dataset.heicConverter='1';script.onload=()=>resolve();script.onerror=()=>reject(new Error('No se pudo cargar el conversor HEIC. Revisá la conexión a Internet.'));document.head.appendChild(script)});if(!w.heic2any)throw new Error('El conversor HEIC no está disponible.');const result=await w.heic2any({blob,toType:'image/jpeg',quality:.92});return (Array.isArray(result)?result[0]:result) as Blob}

function playOrderSound(){try{const AC=(window.AudioContext||((window as any).webkitAudioContext));if(!AC)return;const ctx=new AC();const now=ctx.currentTime;const osc=ctx.createOscillator();const gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(660,now);osc.frequency.exponentialRampToValueAtTime(880,now+0.09);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(0.08,now+0.015);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.18);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+0.2);setTimeout(()=>ctx.close(),260)}catch{}}

